<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Micro-controller vs. Micro-processor</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
            background-color: white;
            display: flex;
            flex-direction: column;
            min-height: 100vh;
        }

        /* Header */
        .header {
            background: linear-gradient(to right, #1a1a7a 0%, #8b8bc3 40%, #e6e6f0 100%);
            color: white;
            padding: 10px 20px 10px 80px;
            font-size: 28px;
            font-weight: bold;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
            position: relative;
            height: 40px;
            display: flex;
            align-items: center;
        }
        .header-squares {
            position: absolute;
            left: 0;
            top: 0;
            height: 100%;
            width: 60px;
        }
        .sq { position: absolute; width: 15px; height: 15px; }
        .sq-dark { background-color: #000080; }
        .sq-med { background-color: #4169E1; }
        .sq-light { background-color: #87CEEB; }
        .sq-pale { background-color: #E6E6FA; }

        /* Main Content */
        .main-container {
            flex: 1;
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 20px;
        }
        .diagram-box {
            background-color: #f2f2f2;
            border: 1px solid #ccc;
            border-radius: 15px;
            padding: 40px 60px;
            display: flex;
            gap: 80px;
            box-shadow: 3px 3px 10px rgba(0,0,0,0.1);
        }

        /* Columns */
        .left-col, .right-col {
            display: flex;
            flex-direction: column;
            align-items: center;
        }
        .col-title {
            font-weight: bold;
            font-size: 22px;
            text-decoration: underline;
            margin-bottom: 25px;
        }

        /* Left Column - Microcontroller */
        .microcontroller-chip {
            background-color: #29aae2;
            border: 2px solid #0071bc;
            padding: 15px;
            display: flex;
            flex-direction: column;
            gap: 12px;
            width: 260px;
        }
        .mc-title {
            text-align: center;
            font-weight: bold;
            font-size: 18px;
            margin-bottom: 5px;
        }
        .mc-row {
            display: flex;
            gap: 12px;
        }
        .mc-box {
            background-color: white;
            border: 1px solid black;
            padding: 10px 5px;
            text-align: center;
            font-weight: bold;
            font-size: 16px;
            display: flex;
            justify-content: center;
            align-items: center;
        }
        .mc-box.cpu { flex: 0.8; }
        .mc-box.timer { flex: 1.2; }
        .mc-box.memory { flex: 1.2; }
        .mc-box.clock { flex: 0.8; }
        .mc-box.io { flex: 1.2; }
        .mc-box.usart { flex: 0.8; }
        .mc-box.peripherals { width: 100%; box-sizing: border-box; }

        /* Right Column - Microprocessor */
        .chips-container {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }
        .chip-row {
            display: flex;
            gap: 20px;
            justify-content: space-between;
        }
        .left-chip {
            width: 220px;
        }
        .right-chip-group {
            width: 280px;
            display: flex;
            gap: 20px;
        }
        .right-chip-single {
            width: 280px;
        }
        .chip-box {
            border: 1px solid black;
            padding: 15px 10px;
            text-align: center;
            font-weight: bold;
            font-size: 18px;
            display: flex;
            justify-content: center;
            align-items: center;
            box-shadow: 2px 2px 5px rgba(0,0,0,0.1);
        }
        .chip-mpu { background-color: #39b54a; color: white; }
        .chip-clock { background-color: #b97a57; color: white; flex: 1; }
        .chip-usart { background-color: #99d9ea; flex: 1.2; }
        .chip-memory { background-color: #00a2e8; color: white; }
        .chip-io { background-color: #fff2cc; }
        .chip-timer { background-color: #c3c3c3; }

        .multi-color-box {
            border: 1px solid black;
            display: flex;
            position: relative;
            box-shadow: 2px 2px 5px rgba(0,0,0,0.1);
        }
        .color-segment {
            flex: 1;
            height: 100%;
        }
        .seg1 { background-color: #c8bfe7; }
        .seg2 { background-color: #fff2cc; }
        .seg3 { background-color: #b5e61d; }
        .seg4 { background-color: #ffaec9; }
        .multi-color-text {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            font-weight: bold;
            font-size: 18px;
        }

        /* Footer */
        .footer {
            display: flex;
            justify-content: space-between;
            padding: 10px 40px 30px 40px;
            font-size: 14px;
        }
        .footer-center {
            flex: 1;
            text-align: center;
        }
        .footer-right {
            font-weight: bold;
            font-size: 16px;
        }
    </style>
</head>
<body>

    <div class="header">
        <div class="header-squares">
            <div class="sq sq-dark" style="top: 0; left: 0;"></div>
            <div class="sq sq-pale" style="top: 15px; left: 0;"></div>
            <div class="sq sq-med" style="top: 30px; left: 0;"></div>
            <div class="sq sq-dark" style="top: 15px; left: 15px;"></div>
            <div class="sq sq-pale" style="top: 30px; left: 15px;"></div>
            <div class="sq sq-med" style="top: 0; left: 30px;"></div>
            <div class="sq sq-light" style="top: 15px; left: 30px;"></div>
        </div>
        Micro-controller vs. Micro-processor
    </div>

    <div class="main-container">
        <div class="diagram-box">

            <!-- Left Column -->
            <div class="left-col">
                <div class="col-title">One Chip</div>
                <div class="microcontroller-chip">
                    <div class="mc-title">Microcontroller</div>
                    <div class="mc-row">
                        <div class="mc-box cpu">CPU</div>
                        <div class="mc-box timer">Timer/Counter</div>
                    </div>
                    <div class="mc-row">
                        <div class="mc-box memory">Memory</div>
                        <div class="mc-box clock">Clock</div>
                    </div>
                    <div class="mc-row">
                        <div class="mc-box io">I/O Interface</div>
                        <div class="mc-box usart">USART</div>
                    </div>
                    <div class="mc-row">
                        <div class="mc-box peripherals">Other Peripherals</div>
                    </div>
                </div>
            </div>

            <!-- Right Column -->
            <div class="right-col">
                <div class="col-title">Many Different Chips</div>
                <div class="chips-container">
                    <div class="chip-row">
                        <div class="chip-box chip-mpu left-chip">Microprocessor</div>
                        <div class="right-chip-group">
                            <div class="chip-box chip-clock">Clock</div>
                            <div class="chip-box chip-usart">USART</div>
                        </div>
                    </div>
                    <div class="chip-row">
                        <div class="chip-box chip-memory left-chip">Memory</div>
                        <div class="chip-box chip-io right-chip-single">I/O Interfaces</div>
                    </div>
                    <div class="chip-row">
                        <div class="chip-box chip-timer left-chip">Timer/Counter</div>
                        <div class="multi-color-box right-chip-single">
                            <div class="color-segment seg1"></div>
                            <div class="color-segment seg2"></div>
                            <div class="color-segment seg3"></div>
                            <div class="color-segment seg4"></div>
                            <div class="multi-color-text">Other Peripherals</div>
                        </div>
                    </div>
                </div>
            </div>

        </div>
    </div>

    <div class="footer">
        <div style="width: 20px;"></div>
        <div class="footer-center">© 2015 by Eng. Mohamed Tarek.</div>
        <div class="footer-right">7</div>
    </div>

</body>
</html>
